    /// let custom_headers = Headers::default()
    ///     .with_env_mapping(EnvMapping {
    ///         bearer_token: Some(EnvList::single("STAGING_TOKEN")),
    ///         basic_user: None,
    ///         basic_pass: None,
    ///         api_key: None,
